@push('styles')<style>.message-file-zones{display:grid;grid-template-columns:1fr 1fr;gap:.75rem}.message-file-drop-zone,.message-file-paste-zone{min-height:105px;border:2px solid #b9c5c5;border-radius:.5rem;background:#f8faf9;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:1.25rem;cursor:pointer}.message-file-drop-zone{border-style:dashed}.message-file-drop-zone:hover,.message-file-drop-zone:focus,.message-file-drop-zone.is-dragging,.message-file-paste-zone:hover,.message-file-paste-zone:focus{border-color:#173f40;background:#f0f6f5;outline:none}.message-file-drop-zone span,.message-file-paste-zone span{color:#6c757d;font-size:.9rem;margin-top:.25rem}@media(max-width:575.98px){.message-file-zones{grid-template-columns:1fr}}.message-file-card{border:1px solid #dbe2e2;border-radius:.4rem;padding:.65rem .8rem;background:#fff}.message-file-card .form-switch{margin:0}</style>@endpush
@endonce
@push('scripts')<script>(()=>{const root=document.getElementById(@json($pickerId)),input=root.querySelector('input[type=file]'),zone=root.querySelector('.message-file-drop-zone'),pasteZone=root.querySelector('.message-file-paste-zone'),fileCards=root.querySelector('.message-file-cards'),documentSelect=root.querySelector('select'),documentCards=root.querySelector('.message-document-cards'),saved=new Set(),selectedDocuments=new Map(),queuedFiles=[];const key=file=>[file.name,file.size,file.lastModified].join(':');function renderFiles(){fileCards.innerHTML='';[...input.files].forEach((file,index)=>{const card=document.createElement('div');card.className='message-file-card d-flex flex-wrap justify-content-between align-items-center gap-3';const info=document.createElement('div');const name=document.createElement('strong');name.textContent=file.name;const size=document.createElement('div');size.className='small text-muted';size.textContent=Math.max(1,Math.round(file.size/1024))+' KB';info.append(name,size);const actions=document.createElement('div');actions.className='d-flex align-items-center gap-3';const label=document.createElement('label');label.className='form-check form-switch';const toggle=document.createElement('input');toggle.className='form-check-input';toggle.type='checkbox';toggle.name='save_in_documents[]';toggle.value=index;toggle.checked=saved.has(key(file));toggle.addEventListener('change',()=>toggle.checked?saved.add(key(file)):saved.delete(key(file)));const text=document.createElement('span');text.className='form-check-label';text.textContent='Save in Documents';label.append(toggle,text);const remove=document.createElement('button');remove.type='button';remove.className='btn-close';remove.ariaLabel='Remove '+file.name;remove.addEventListener('click',()=>removeFile(index));actions.append(label,remove);card.append(info,actions);fileCards.append(card)})}function setFiles(files){const transfer=new DataTransfer();[...files].slice(0,5).forEach(file=>transfer.items.add(file));input.files=transfer.files;queuedFiles.splice(0,queuedFiles.length,...input.files);renderFiles()}function addFiles(files){setFiles([...queuedFiles,...files])}function removeFile(index){const files=[...input.files],removed=files.splice(index,1)[0];saved.delete(key(removed));setFiles(files)}function clientId(){if(root.dataset.fixedClient)return root.dataset.fixedClient;const search=document.getElementById(root.dataset.clientSearch),option=[...document.querySelectorAll('#client_options option')].find(option=>option.value===search?.value);return option?.dataset.id||''}function filterDocuments(){const id=clientId();let count=0;[...documentSelect.options].forEach((option,index)=>{if(index===0)return;option.hidden=!!id&&option.dataset.clientId!==id;if(!option.hidden&&!selectedDocuments.has(option.value))count++});documentSelect.disabled=!id;documentSelect.options[0].textContent=id?(count?'Choose a document':'No shared documents available'):'Select a client first';documentSelect.value=''}function renderDocuments(){documentCards.innerHTML='';selectedDocuments.forEach((name,id)=>{const card=document.createElement('div');card.className='message-file-card d-flex justify-content-between align-items-center gap-3';const label=document.createElement('strong');label.textContent=name;const hidden=document.createElement('input');hidden.type='hidden';hidden.name='shared_document_ids[]';hidden.value=id;const remove=document.createElement('button');remove.type='button';remove.className='btn-close';remove.ariaLabel='Remove '+name;remove.addEventListener('click',()=>{selectedDocuments.delete(id);renderDocuments();filterDocuments()});card.append(label,hidden,remove);documentCards.append(card)})}zone.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();input.click()}});zone.addEventListener('dragover',event=>{event.preventDefault();zone.classList.add('is-dragging')});zone.addEventListener('dragleave',()=>zone.classList.remove('is-dragging'));zone.addEventListener('drop',event=>{event.preventDefault();zone.classList.remove('is-dragging');addFiles(event.dataTransfer.files)});pasteZone.addEventListener('paste',event=>{const images=[...event.clipboardData.files].filter(file=>file.type.startsWith('image/'));if(!images.length)return;event.preventDefault();addFiles(images)});input.addEventListener('change',()=>addFiles(input.files));documentSelect.addEventListener('change',()=>{const option=documentSelect.selectedOptions[0];if(!option.value||selectedDocuments.size>=5)return;selectedDocuments.set(option.value,option.dataset.name);renderDocuments();filterDocuments()});if(root.dataset.clientSearch)document.getElementById(root.dataset.clientSearch)?.addEventListener('input',()=>setTimeout(filterDocuments));filterDocuments();setTimeout(filterDocuments)})()</script>@endpush
